WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_data_growth_compare'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '增长比较', 'kp-xingce-data-growth-compare', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "增长量比较"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "不用算出具体数值，通过口诀比较多个主体增量大小的秒杀技巧。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "题干包含：“……比上年（同比）增长最多的是？”、“……增量最大/最小的是？”。这是最经典的排序选择题。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式与口诀"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "根据增长量公式的分子部分得出核心比较口诀："}]}, {"type": "paragraph", "content": [{"type": "text", "text": "1. 大大则大（秒杀）：", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 现期量大，且增长率也大，则增量必然大。"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "2. 一大一小看乘积：", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 现期量大但增长率小，直接比较 "}, {"type": "text", "text": "现期量 × 增长率", "marks": [{"type": "bold"}, {"type": "textStyle", "color": "#2563eb"}]}, {"type": "text", "text": " 的乘积，乘积大的增量大概率更大。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[列出四个选项的现期量与增速] --> B{是否存在'大大'关系?}\nB -- 有 --> C[利用'大大则大'排掉较小的选项]\nB -- 没有 --> D[剩余选项进入'一大一小'对决]\nD --> E[估算 现期量 × 增长率 的乘积]\nE --> F[选出乘积最大/最小的对应项]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 产量及增速：小麦(450, 12%)，玉米(320, 15%)，大豆(480, 14%)，高粱(210, 28%)。问增量最多的是？选项：A.小麦 B.玉米 C.大豆 D.高粱"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "大大则大排雷：大豆(480,14%) 现期量和增速都大于 小麦(450,12%)，大豆增量必大于小麦，排除A。同理大豆也全包围玉米(320,15%)，排除B。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "一大一小决战：大豆(480,14%) vs 高粱(210,28%)。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "看乘积：大豆乘积 = 480 × 14% ≈ 67；高粱乘积 = 210 × 28% ≈ 58。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "锁定答案：67 > 58，大豆增量最大，选 C。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "乘积接近时强行判定：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "如果算出来的乘积几乎一样（如 45 和 46），此时必须回归严谨的分式 乘积/(1+r) 进行比较。因为分母的不同可能会反转大小关系！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "熟练掌握快速估算乘积的能力。遇到减少量比较时，直接把减少率取绝对值当成正数，继续用“大大则大看乘积”口诀。"}]}]}$$ AS jsonb), NULL, '增长比较的核心考点与实战推导。', category_node.id, CAST('["资料分析", "增长比较"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_growth_compare", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
